export function toMeasurementCborValue(v: Measurement): CborValue {
  const csilMap = new Map<CborValue, CborValue>();
  csilMap.set("key", v.key);
  csilMap.set("kind", v.kind);
  if (v.unit !== undefined) csilMap.set("unit", v.unit);
  if (v.intValue !== undefined) csilMap.set("int_value", v.intValue);
  if (v.floatValue !== undefined) csilMap.set("float_value", v.floatValue);
  if (v.decimalValue !== undefined) csilMap.set("decimal_value", { tag: 4, value: v.decimalValue.toTag4() });
  return csilMap;
}

export function fromMeasurementCborValue(value: CborValue): Measurement {
  return {
    key: asString(requireKey(value, "key")),
    kind: (asEnumMember(asString(requireKey(value, "kind")), ["float", "decimal", "int"]) as "float" | "decimal" | "int"),
    floatValue: ((csilV: CborValue | undefined) => csilV === undefined ? undefined : asNumber(csilV))(mapGet(value, "float_value")),
    decimalValue: ((csilV: CborValue | undefined) => csilV === undefined ? undefined : CsilDecimal.fromTag4(asDecimalPayload(csilV)))(mapGet(value, "decimal_value")),
    intValue: ((csilV: CborValue | undefined) => csilV === undefined ? undefined : asNumber(csilV))(mapGet(value, "int_value")),
    unit: ((csilV: CborValue | undefined) => csilV === undefined ? undefined : asString(csilV))(mapGet(value, "unit")),
  };
}

export function toMeasurementCbor(v: Measurement): Uint8Array {
  return encodeValue(toMeasurementCborValue(v));
}

export function fromMeasurementCbor(bytes: Uint8Array): Measurement {
  return fromMeasurementCborValue(decode(bytes));
}

